## Expected Answer

Strong candidates discuss CSS Grid auto-fit/minmax, virtual scrolling implementation, CSS transform-based animations for GPU acceleration, and batched DOM updates using requestAnimationFrame or DocumentFragment.

## Code Example

```javascript
// Virtualized grid with performant updates
class VirtualizedGrid {
  constructor(container, data) {
    this.container = container;
    this.data = data;
 this.visibleItems = [];
    this.itemHeight = 50;
    this.bufferSize = 5;

    this.setupGrid();
    this.bindEvents();
  }

  setupGrid() {
    this.container.style.display = 'grid';
    this.container.style.gridTemplateColumns = 'repeat(auto-fit, minmax(200px, 1fr))';
    this.container.style.gap = '16px';
    this.container.style.height = '400px';
    this.container.style.overflow = 'auto';
  }

  updateVisibleItems() {
    const scrollTop = this.container.scrollTop;
    const containerHeight = this.container.clientHeight;
    const startIndex = Math.max(0, Math.floor(scrollTop / this.itemHeight) - this.bufferSize);
    const endIndex = Math.min(this.data.length, Math.ceil((scrollTop + containerHeight) / this.itemHeight) + this.bufferSize);

    requestAnimationFrame(() => {
      this.renderItems(startIndex, endIndex);
    });
  }

  renderItems(startIndex, endIndex) {
    const fragment = document.createDocumentFragment();

    // Clear existing items
    this.container.innerHTML = '';

    // Render visible items
    for (let i = startIndex; i < endIndex; i++) {
      const item = this.createItem(this.data[i], i);
      fragment.appendChild(item);
    }

    this.container.appendChild(fragment);
  }

  createItem(data, index) {
    const item = document.createElement('div');
    item.className = 'grid-item';
    item.textContent = data.title;
    item.style.transform = `translateY(${index * this.itemHeight}px)`;
    item.style.transition = 'transform 0.3s ease';

    // Use transform for position changes (GPU accelerated)
    item.addEventListener('click', () => {
      item.style.transform = `translateY(${index * this.itemHeight}px) scale(1.05)`;
      setTimeout(() => {
        item.style.transform = `translateY(${index * this.itemHeight}px) scale(1)`;
      }, 200);
    });

    return item;
  }

  bindEvents() {
    this.container.addEventListener('scroll', () => {
      this.updateVisibleItems();
    });

    window.addEventListener('resize', () => {
      this.updateVisibleItems();
    });
  }

  // Batch update for large datasets
  updateData(newData) {
    this.data = newData;

    // Use requestAnimationFrame for smooth updates
    requestAnimationFrame(() => {
      this.updateVisibleItems();
    });
  }

  // Reorder items with animation
  reorderItems(fromIndex, toIndex) {
    const item = this.data[fromIndex];
    this.data.splice(fromIndex, 1);
    this.data.splice(toIndex, 0, item);

    // Animate the reordering
    requestAnimationFrame(() => {
      this.updateVisibleItems();
    });
  }
}

// Performance monitoring
const performanceMonitor = {
  measureFPS() {
    let lastTime = performance.now();
    let frames = 0;

    function measure() {
      frames++;
      const currentTime = performance.now();

      if (currentTime >= lastTime + 1000) {
        const fps = Math.round((frames * 1000) / (currentTime - lastTime));
        console.log(`FPS: ${fps}`);
        frames = 0;
        lastTime = currentTime;
      }

      requestAnimationFrame(measure);
    }

    requestAnimationFrame(measure);
  }
};
```

## Why This Is Asked
This question evaluates advanced JavaScript patterns including per-key caching, Promise deduplication, TTL-based eviction, and reactive update patterns commonly needed in frontend applications.

## Key Concepts
- **Closures and per-key maps**: Isolated state management for each cached key
- **Promise deduplication**: Avoiding redundant network requests for concurrent loads of the same key
- **TTL-based eviction**: Time-to-live expiration for cache entries
- **Change notifications**: Listener pattern for broadcasting data updates
- **Error handling**: Graceful handling of fetch failures and cache misses

## Code Example
```javascript
function createDataLoader(fetchFn, ttlMs) {
  const cache = new Map();

  function getEntry(key) {
    if (!cache.has(key)) {
      cache.set(key, { promise: null, data: null, expiry: 0, listeners: [] });
    }
    return cache.get(key);
  }

  const notify = (key, data, error) => {
    const entry = cache.get(key);
    if (entry?.listeners.length) {
      entry.listeners.forEach(cb => cb(data, error));
    }
  };

  return {
    load(key) {
      const entry = getEntry(key);
      const now = Date.now();

      if (entry.data && entry.expiry > now) {
        return Promise.resolve(entry.data);
      }

      if (entry.promise) {
        return entry.promise;
      }

      entry.promise = fetchFn(key)
        .then(data => {
          entry.data = data;
          entry.expiry = now + ttlMs;
          entry.promise = null;
          notify(key, data, null);
          return data;
        })
        .catch(err => {
          entry.promise = null;
          notify(key, null, err);
          throw err;
        });

      return entry.promise;
    },

    invalidate(key) {
      const entry = cache.get(key);
      if (entry) {
        entry.data = null;
        entry.expiry = 0;
        entry.promise = null;
      }
    },

    onChange(key, cb) {
      const entry = getEntry(key);
      entry.listeners.push(cb);
      return () => {
        entry.listeners = entry.listeners.filter(l => l !== cb);
      };
    }
  };
}
```

## Usage Example
```javascript
const loader = createDataLoader(fetchUser, 5000);

// Two different keys
loader.onChange('user:1', (data) => console.log('User 1 updated:', data));
loader.onChange('user:2', (data) => console.log('User 2 updated:', data));

// Concurrent loads for same key are deduplicated
loader.load('user:1').then(console.log);
loader.load('user:1').then(console.log); // Reuses in-flight request

// Invalidate and reload
loader.invalidate('user:1');
loader.load('user:1');
```

## Eviction Strategies
- **TTL-based**: Automatic expiration after ttlMs (implemented above)
- **LRU**: Evict least recently used entries when cache size exceeds limit
- **Manual**: Explicit invalidate() calls

## Error Handling
- Failed fetches propagate errors to all waiters via rejected Promise
- Listeners receive error state for reactive UI updates
- In-flight promises are cleared on error to allow retries

